/**
 * @name Path traversal in file operations
 * @description User-controlled input used in file operations without proper sanitization can lead to path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // File operations that could be vulnerable to path traversal
    exists(FileSystemAccess fa |
      sink = fa.getAPathArgument()
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal vulnerability: user input flows to file operation at $@.", source.getNode(), "user input"

/**
 * @name Command injection in aiohttp
 * @description User-controlled input flowing to command execution functions like os.system, subprocess.call, etc.
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Use API graphs to find command execution functions
    exists(API::CallNode call |
      // os.system
      call = API::moduleImport("os").getMember("system").getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      // subprocess.call
      call = API::moduleImport("subprocess").getMember("call").getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      // subprocess.Popen
      call = API::moduleImport("subprocess").getMember("Popen").getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      // subprocess.run
      call = API::moduleImport("subprocess").getMember("run").getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      // os.popen
      call = API::moduleImport("os").getMember("popen").getACall() and
      sink = call.getArg(0)
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"

/**
 * @name XSS in aiohttp
 * @description User-controlled input flowing to HTML output without proper escaping
 * @kind path-problem
 * @problem.severity error
 * @id py/xss
 * @tags security
 *        external/cwe/cwe-079
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module XssConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for HTML output methods
    exists(API::CallNode call |
      // web.Response text output
      call = API::moduleImport("aiohttp.web").getMember("Response").getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      // Direct string concatenation with HTML
      call = API::builtin("str").getMember("__add__").getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      // String formatting
      call = API::builtin("str").getMember("format").getACall() and
      sink = call.getArg(0)
    )
  }
}

module XssFlow = TaintTracking::Global<XssConfig>;
import XssFlow::PathGraph

from XssFlow::PathNode source, XssFlow::PathNode sink
where XssFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential XSS vulnerability from $@.", source.getNode(), "user input"
